import{fetchWithCsrf}from"./api.js";const PANEL_STATE_CLASSES=["panel-state--loading","panel-state--error"];function setDbPanelState(e,t){const r=document.getElementById("db-panel-state");r&&(r.textContent=e,r.hidden="hidden"===t,r.classList.remove(...PANEL_STATE_CLASSES),"loading"===t&&r.classList.add("panel-state--loading"),"error"===t&&r.classList.add("panel-state--error"))}export function setDbStatus(e,t){const r=document.getElementById("db-status-msg");if(!r)return;if(!e)return void(r.hidden=!0);r.hidden=!1,r.textContent=e;const s={error:{bg:"#fee2e2",color:"#ef4444",border:"1px solid #fca5a5"},success:{bg:"#dcfce7",color:"#10b981",border:"1px solid #86efac"},info:{bg:"#eff6ff",color:"#3b82f6",border:"1px solid #93c5fd"}},o=s[t]||s.info;r.style.background=o.bg,r.style.color=o.color,r.style.border=o.border}function handleDbSuccess(e){setDbStatus(`Ping ${e?`${e}ms`:"—"}`,"success"),setDbPanelState("","hidden")}function handleDbError(e){setDbStatus(`Ошибка: ${e||"Невозможно проверить базу"}`,"error"),setDbPanelState("Невозможно получить статус базы данных","error")}async function fetchDbPayload(){const e=await fetch("/api/super/system/db");if(!e.ok)throw new Error("Не удалось получить статус");return e.json()}export async function refreshDbPanelStatus(){setDbPanelState("Проверяем доступность базы данных...","loading"),setDbStatus("","info");try{const e=await fetchDbPayload(),t=e?.db;return t?.connected?handleDbSuccess(t.pingMs):handleDbError(e?.error||t?.lastError)}catch(e){handleDbError(e.message)}}export async function handleRestore(e){if(e){setDbStatus("Восстановление...","info");try{const t=await fetchWithCsrf("/api/super/db-restore",{method:"POST",body:e,headers:{"Content-Type":"application/octet-stream"}}),r=await t.json();t.ok&&r.success?(setDbStatus("Успешно! Перезагрузка...","success"),setTimeout(()=>window.location.reload(),2e3)):setDbStatus("Ошибка: "+(r.error||"Unknown"),"error")}catch(e){setDbStatus("Ошибка связи","error")}}}